#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY

#define NUM_MEMORY_SLOTS 1
#define SURFER_LAST 9
#define GSOk 0
#define GSErrorUnformatted -1

class Career
{
public:
	int GetSurferIdx();
};

extern Career *g_career;

class GenericGameSaver
{
public:
	static GenericGameSaver *inst();
	int getInfo(int port, int slot, int *type, int *free, int *formatted);
};

struct MemCard
{
	int free;
	bool exists;
	bool changed;
	bool available;
	bool ask_format;
	bool saved_games;
	int status;
};

class SaveLoadFrontEnd
{
	char data[0x32c4];
	int dstate;
public:
	enum { DSTATE_SAVE = 7 };
	int GetDState() { return dstate; }
	void EndError(int id);
};

class NamesMenu
{
	char data0[0x170];
	SaveLoadFrontEnd *sl_parent;
	char data1[0x48];
	MemCard cards[2];
	stringx blank_name;
	int active_card;
	int adjusted_active_card;
	bool cardSide;
	PanelQuad *box;
	PanelQuad *arrows[2][2];
	PanelQuad *lines[10], *top_line, *side_line;
	FEMenuEntry *entry[17];
public:
	static int FindAdjusted(int active);
	stringx MakeCardName(int active);
	void CheckCardNum(int card_num);
};

__asm__(".equ GetSurferIdx__6Career, 0x0025A7C0");
__asm__(".equ getInfo__16GenericGameSaveriiPiN23, 0x001E3DC0");
__asm__(".equ _16GenericGameSaver$instance, 0x0042E5B8");
__asm__(".equ FindAdjusted__9NamesMenui, 0x001A0808");
__asm__(".equ MakeCardName__9NamesMenui, 0x0019E588");
__asm__(".equ EndError__16SaveLoadFrontEndi, 0x0019B5A0");
__asm__(".equ g_career, 0x00427C9C");

GenericGameSaver *GenericGameSaver::inst()
{
	extern GenericGameSaver *instance
		__asm__("_16GenericGameSaver$instance");
	return instance;
}

void NamesMenu::CheckCardNum(int card_num)
{
	int adjust = NamesMenu::FindAdjusted(card_num);
	int type=0, formatted=0;
	cards[adjust].free = 0;
	int ret;
	bool allow_save_errors = true;

	if( g_career->GetSurferIdx() == SURFER_LAST && sl_parent->GetDState()== SaveLoadFrontEnd::DSTATE_SAVE )
		allow_save_errors = false;

	ret = GenericGameSaver::inst()->getInfo((card_num!=-1)?card_num/NUM_MEMORY_SLOTS:-1, (card_num!=-1)?card_num%NUM_MEMORY_SLOTS:0, &type, &(cards[adjust].free), &formatted);

	int status_before = cards[adjust].status;

	cards[adjust].status = ret;

	cards[adjust].exists = true;
	cards[adjust].available = false;

	switch(ret)
	{
	case GSOk:
		cards[adjust].exists = true;
		cards[adjust].available = true;
		break;
	case GSErrorUnformatted:
		//The default
		break;
	default:
		cards[adjust].exists = false;
		cards[adjust].available = false;
		break;
	}
	cards[adjust].changed = cards[adjust].status != status_before;
	if (cards[adjust].changed)
		entry[adjust+15]->SetText(MakeCardName(card_num));

	if( cards[adjust].changed )
		sl_parent->EndError( -1 );
//	entry[adjust+num]->Disable(!cards[adjust].exists && !save);
}
